def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = []
    stack = [0]
    parent[0] = -2
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                stack.append(v)

    sub = [0] * n
    total = 0
    for u in reversed(order):
        s = w[u]
        for v in adj[u]:
            if parent[v] == u:
                s += sub[v]
        sub[u] = s
        total += w[u]

    ans = [0] * n
    depth = [0] * n
    for u in order:
        if u:
            depth[u] = depth[parent[u]] + 1
        ans[0] += w[u] * depth[u]

    for u in order:
        if u:
            ans[u] = ans[parent[u]] + total - 2 * sub[u]
    return ans
